// Media queries for the layout, adjacent so every width falls in exactly one
// range. The values are the design system's breakpoints (v4: small ends at 767).
export const BREAKPOINT_MOBILE = '(max-width: 767px)';
export const BREAKPOINT_TABLET = '(min-width: 768px) and (max-width: 1023px)';
export const BREAKPOINT_DESKTOP = '(min-width: 1024px)';

export function matches(query: string): boolean {
  return globalThis.matchMedia(query).matches;
}
